WITH eligible AS (
 SELECT s.School,s.Phone,x.NumGE1500
 FROM schools s JOIN satscores x ON x.cds=s.CDSCode
 WHERE s.Charter=1 AND s.FundingType='Directly funded' AND s.DOC='00'
 AND x.NumGE1500 IS NOT NULL
), ranked AS (
 SELECT School,Phone,NumGE1500,DENSE_RANK() OVER (ORDER BY NumGE1500 DESC) r
 FROM eligible
)
SELECT School,Phone,NumGE1500 FROM ranked WHERE r=1;

