WITH race AS (
  SELECT raceId FROM races WHERE year = 1957 AND name = 'British Grand Prix'
), entries AS (
  SELECT res.resultId, st.status
  FROM results res
  JOIN race r ON r.raceId = res.raceId
  JOIN status st ON st.statusId = res.statusId
)
SELECT ROUND(100.0 * SUM(CASE WHEN status = 'Finished' OR status GLOB '+* Lap*' THEN 1 ELSE 0 END) / COUNT(*), 2) AS percentage
FROM entries;

